-- PCO Prime Sync — SQLite schema
-- All timestamps are ISO-8601 UTC strings generated by the application.

PRAGMA journal_mode = WAL;
PRAGMA foreign_keys = ON;

-- Single-row application settings. Credentials are deliberately NOT stored here:
-- PCO_APP_ID / PCO_SECRET live in the environment or the macOS Keychain.
CREATE TABLE IF NOT EXISTS church_settings (
  id                    INTEGER PRIMARY KEY CHECK (id = 1),
  pco_app_id            TEXT,
  pco_service_type_ids  TEXT NOT NULL DEFAULT '[]',
  pco_team_ids          TEXT NOT NULL DEFAULT '[]',
  prime_base_url        TEXT NOT NULL DEFAULT 'https://loopcommunity.com',
  prime_profile_dir     TEXT NOT NULL DEFAULT 'profiles/prime',
  prime_headless        INTEGER NOT NULL DEFAULT 0,
  sync_hour             INTEGER NOT NULL DEFAULT 3,
  sync_minute           INTEGER NOT NULL DEFAULT 0,
  timezone              TEXT NOT NULL DEFAULT 'America/New_York',
  window_days           INTEGER NOT NULL DEFAULT 21,
  auto_sync_enabled     INTEGER NOT NULL DEFAULT 0,
  created_at            TEXT NOT NULL,
  updated_at            TEXT NOT NULL
);

-- Which PCO teams count as worship teams. Production / tech teams stay unselected.
CREATE TABLE IF NOT EXISTS pco_team_configuration (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  team_id           TEXT NOT NULL UNIQUE,
  team_name         TEXT NOT NULL,
  service_type_id   TEXT,
  is_worship_team   INTEGER NOT NULL DEFAULT 0,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);

-- One row per PCO plan we have seen, with the last synchronization status.
CREATE TABLE IF NOT EXISTS service_plans (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  pco_plan_id     TEXT NOT NULL UNIQUE,
  service_type_id TEXT NOT NULL,
  title           TEXT NOT NULL,
  series_title    TEXT,
  sort_date       TEXT,
  plan_date       TEXT NOT NULL,
  status          TEXT NOT NULL DEFAULT 'not_synced',
  last_synced_at  TEXT,
  pco_updated_at  TEXT,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_service_plans_plan_date ON service_plans (plan_date);

-- Confirmed PCO song name -> Loop multitrack mappings, keyed by normalized name.
CREATE TABLE IF NOT EXISTS song_mappings (
  id                    INTEGER PRIMARY KEY AUTOINCREMENT,
  normalized_name       TEXT NOT NULL UNIQUE,
  pco_song_id           TEXT,
  pco_song_title        TEXT NOT NULL,
  prime_track_id        TEXT NOT NULL,
  prime_track_name      TEXT NOT NULL,
  prime_arrangement_id  TEXT,
  prime_arrangement_name TEXT,
  confirmed             INTEGER NOT NULL DEFAULT 0,
  source                TEXT NOT NULL DEFAULT 'manual',
  created_at            TEXT NOT NULL,
  updated_at            TEXT NOT NULL
);

-- Songs inside a plan: PCO order/key/arrangement + resolved Prime identity.
CREATE TABLE IF NOT EXISTS plan_songs (
  id                      INTEGER PRIMARY KEY AUTOINCREMENT,
  plan_id                 INTEGER NOT NULL REFERENCES service_plans (id) ON DELETE CASCADE,
  pco_item_id             TEXT NOT NULL,
  pco_song_id             TEXT,
  position                INTEGER NOT NULL,
  title                   TEXT NOT NULL,
  normalized_title        TEXT NOT NULL,
  arrangement_selected    TEXT NOT NULL DEFAULT 'none',
  arrangement_pco_id      TEXT,
  arrangement_pco_name    TEXT,
  key_name                TEXT,
  bpm                     REAL,
  match_status            TEXT NOT NULL DEFAULT 'unmatched',
  song_mapping_id         INTEGER REFERENCES song_mappings (id) ON DELETE SET NULL,
  prime_track_id          TEXT,
  prime_track_name        TEXT,
  prime_setlist_track_id  TEXT,
  prime_applied_key       TEXT,
  created_at              TEXT NOT NULL,
  updated_at              TEXT NOT NULL,
  UNIQUE (plan_id, pco_item_id)
);
CREATE INDEX IF NOT EXISTS idx_plan_songs_plan ON plan_songs (plan_id, position);

-- Scheduled worship musicians for a plan (production volunteers excluded).
CREATE TABLE IF NOT EXISTS plan_musicians (
  id                      INTEGER PRIMARY KEY AUTOINCREMENT,
  plan_id                 INTEGER NOT NULL REFERENCES service_plans (id) ON DELETE CASCADE,
  pco_person_id           TEXT NOT NULL,
  pco_name                TEXT NOT NULL,
  email_normalized        TEXT,
  email_raw               TEXT,
  team_id                 TEXT,
  team_name               TEXT,
  match_status            TEXT NOT NULL DEFAULT 'unmatched',
  team_member_mapping_id  INTEGER REFERENCES team_member_mappings (id) ON DELETE SET NULL,
  prime_member_id         TEXT,
  prime_member_name       TEXT,
  shared                  INTEGER NOT NULL DEFAULT 0,
  created_at              TEXT NOT NULL,
  updated_at              TEXT NOT NULL,
  UNIQUE (plan_id, pco_person_id)
);
CREATE INDEX IF NOT EXISTS idx_plan_musicians_plan ON plan_musicians (plan_id);

-- Confirmed PCO email -> Prime team member mappings.
CREATE TABLE IF NOT EXISTS team_member_mappings (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  normalized_email  TEXT NOT NULL UNIQUE,
  pco_person_id     TEXT,
  pco_name          TEXT,
  prime_member_id   TEXT NOT NULL,
  prime_member_name TEXT NOT NULL,
  status            TEXT NOT NULL DEFAULT 'matched',
  source            TEXT NOT NULL DEFAULT 'manual',
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);

-- The Loop setlist that corresponds to a PCO plan, plus last verified Loop state.
CREATE TABLE IF NOT EXISTS prime_setlists (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  pco_plan_id       TEXT NOT NULL UNIQUE,
  prime_setlist_id  TEXT NOT NULL,
  prime_setlist_name TEXT NOT NULL,
  prime_url         TEXT,
  last_verified_at  TEXT,
  state_json        TEXT NOT NULL DEFAULT '{"tracks":[],"shares":[]}',
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);

-- One row per synchronization attempt (manual, scheduled, CLI, dry run).
CREATE TABLE IF NOT EXISTS sync_history (
  id               INTEGER PRIMARY KEY AUTOINCREMENT,
  started_at       TEXT NOT NULL,
  finished_at      TEXT,
  mode             TEXT NOT NULL,
  trigger          TEXT NOT NULL,
  status           TEXT NOT NULL,
  plans_processed  INTEGER NOT NULL DEFAULT 0,
  changes_applied  INTEGER NOT NULL DEFAULT 0,
  errors_count     INTEGER NOT NULL DEFAULT 0,
  summary          TEXT
);

-- Every planned/applied/skipped change belonging to a run.
CREATE TABLE IF NOT EXISTS sync_changes (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  sync_run_id  INTEGER NOT NULL REFERENCES sync_history (id) ON DELETE CASCADE,
  pco_plan_id  TEXT,
  change_type  TEXT NOT NULL,
  description  TEXT NOT NULL,
  status       TEXT NOT NULL,
  detail       TEXT,
  created_at   TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_sync_changes_run ON sync_changes (sync_run_id);

-- Errors and warnings. Never contains secrets, cookies or tokens.
CREATE TABLE IF NOT EXISTS sync_errors (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  sync_run_id  INTEGER REFERENCES sync_history (id) ON DELETE SET NULL,
  pco_plan_id  TEXT,
  scope        TEXT NOT NULL,
  code         TEXT NOT NULL,
  message      TEXT NOT NULL,
  detail       TEXT,
  created_at   TEXT NOT NULL,
  resolved_at  TEXT
);
CREATE INDEX IF NOT EXISTS idx_sync_errors_created ON sync_errors (created_at);
CREATE INDEX IF NOT EXISTS idx_sync_errors_unresolved ON sync_errors (resolved_at);
